export interface User {
  id: string;
  name: string;
  email: string;
}

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export type TaskStatus = 'todo' | 'in-progress' | 'done';

export interface Task {
  id: string;
  projectId: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
}

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  text: string;
  createdAt: number; // Timestamp
}

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: number; // Timestamp
}

// Event Payloads
export interface TaskAssignedEvent {
  taskId: string;
  projectId: string;
  assigneeId: string;
  previousAssigneeId: string | null;
}

export interface TaskStatusChangedEvent {
  taskId: string;
  projectId: string;
  newStatus: TaskStatus;
  oldStatus: TaskStatus;
}

export interface CommentAddedEvent {
  commentId: string;
  taskId: string;
  authorId: string;
  text: string;
}

type EventCallback = (payload: any) => void;

export class EventBus {
  private subscribers: Map<string, EventCallback[]> = new Map();

  publish<T>(eventName: string, payload: T): void {
    const callbacks = this.subscribers.get(eventName);
    if (callbacks) {
      callbacks.forEach(callback => {
        try {
          callback(payload);
        } catch (error) {
          console.error(`Error in event subscriber for ${eventName}:`, error);
        }
      });
    }
  }

  subscribe(eventName: string, callback: EventCallback): void {
    if (!this.subscribers.has(eventName)) {
      this.subscribers.set(eventName, []);
    }
    this.subscribers.get(eventName)?.push(callback);
  }

  unsubscribe(eventName: string, callback: EventCallback): void {
    const callbacks = this.subscribers.get(eventName);
    if (callbacks) {
      this.subscribers.set(eventName, callbacks.filter(cb => cb !== callback));
    }
  }
}

import { User } from '../types';
import { randomUUID } from 'crypto';

export class UserService {
  private users: Map<string, User> = new Map();

  constructor() {
    // Seed some initial data
    this.createUser('Alice Smith', 'alice@example.com');
    this.createUser('Bob Johnson', 'bob@example.com');
  }

  public createUser(name: string, email: string): User {
    const newUser: User = {
      id: randomUUID(),
      name,
      email,
    };
    this.users.set(newUser.id, newUser);
    return newUser;
  }

  public getUserById(id: string): User | undefined {
    return this.users.get(id);
  }

  public getAllUsers(): User[] {
    return Array.from(this.users.values());
  }

  public updateUser(id: string, name?: string, email?: string): User | undefined {
    const user = this.users.get(id);
    if (user) {
      if (name !== undefined) user.name = name;
      if (email !== undefined) user.email = email;
      return user;
    }
    return undefined;
  }

  public deleteUser(id: string): boolean {
    return this.users.delete(id);
  }
}

import { Project } from '../types';
import { randomUUID } from 'crypto';

export class ProjectService {
  private projects: Map<string, Project> = new Map();

  public createProject(name: string, description: string, initialMemberIds: string[] = []): Project {
    const newProject: Project = {
      id: randomUUID(),
      name,
      description,
      memberIds: [...new Set(initialMemberIds)], // Ensure unique members
    };
    this.projects.set(newProject.id, newProject);
    return newProject;
  }

  public getProjectById(id: string): Project | undefined {
    return this.projects.get(id);
  }

  public getAllProjects(): Project[] {
    return Array.from(this.projects.values());
  }

  public updateProject(id: string, name?: string, description?: string): Project | undefined {
    const project = this.projects.get(id);
    if (project) {
      if (name !== undefined) project.name = name;
      if (description !== undefined) project.description = description;
      return project;
    }
    return undefined;
  }

  public addProjectMember(projectId: string, userId: string): Project | undefined {
    const project = this.projects.get(projectId);
    if (project && !project.memberIds.includes(userId)) {
      project.memberIds.push(userId);
      return project;
    }
    return undefined;
  }

  public removeProjectMember(projectId: string, userId: string): Project | undefined {
    const project = this.projects.get(projectId);
    if (project) {
      const initialLength = project.memberIds.length;
      project.memberIds = project.memberIds.filter(memberId => memberId !== userId);
      if (project.memberIds.length < initialLength) {
        return project;
      }
    }
    return undefined;
  }

  public deleteProject(id: string): boolean {
    return this.projects.delete(id);
  }
}

import { Task, TaskStatus, TaskAssignedEvent, TaskStatusChangedEvent } from '../types';
import { EventBus } from '../event-bus';
import { randomUUID } from 'crypto';

export class TaskService {
  private tasks: Map<string, Task> = new Map();
  private eventBus: EventBus;

  constructor(eventBus: EventBus) {
    this.eventBus = eventBus;
  }

  public createTask(projectId: string, title: string, description: string, assigneeId: string | null = null): Task {
    const newTask: Task = {
      id: randomUUID(),
      projectId,
      title,
      description,
      status: 'todo',
      assigneeId,
    };
    this.tasks.set(newTask.id, newTask);
    return newTask;
  }

  public getTaskById(id: string): Task | undefined {
    return this.tasks.get(id);
  }

  public getTasksByProjectId(projectId: string): Task[] {
    return Array.from(this.tasks.values()).filter(task => task.projectId === projectId);
  }

  public getAllTasks(): Task[] {
    return Array.from(this.tasks.values());
  }

  public updateTask(id: string, title?: string, description?: string): Task | undefined {
    const task = this.tasks.get(id);
    if (task) {
      if (title !== undefined) task.title = title;
      if (description !== undefined) task.description = description;
      return task;
    }
    return undefined;
  }

  public updateTaskStatus(id: string, newStatus: TaskStatus): Task | undefined {
    const task = this.tasks.get(id);
    if (!task) return undefined;

    const oldStatus = task.status;

    // Validate status transitions
    if (oldStatus === 'todo' && newStatus === 'done') return undefined; // Cannot skip in-progress
    if (oldStatus === 'in-progress' && newStatus === 'todo') return undefined; // Cannot go backward
    if (oldStatus === 'done' && newStatus !== 'done') return undefined; // Cannot change from done
    if (oldStatus === newStatus) return task; // No change

    task.status = newStatus;

    // Publish event
    this.eventBus.publish<TaskStatusChangedEvent>('task.statusChanged', {
      taskId: task.id,
      projectId: task.projectId,
      newStatus,
      oldStatus,
    });

    return task;
  }

  public assignTask(taskId: string, assigneeId: string | null): Task | undefined {
    const task = this.tasks.get(taskId);
    if (!task) return undefined;

    const previousAssigneeId = task.assigneeId;
    if (previousAssigneeId === assigneeId) return task; // No change

    task.assigneeId = assigneeId;

    // Publish event
    this.eventBus.publish<TaskAssignedEvent>('task.assigned', {
      taskId: task.id,
      projectId: task.projectId,
      assigneeId,
      previousAssigneeId,
    });

    return task;
  }

  public deleteTask(id: string): boolean {
    return this.tasks.delete(id);
  }
}

import { Comment, CommentAddedEvent } from '../types';
import { EventBus } from '../event-bus';
import { randomUUID } from 'crypto';

export class CommentService {
  private comments: Map<string, Comment> = new Map();
  private eventBus: EventBus;

  constructor(eventBus: EventBus) {
    this.eventBus = eventBus;
  }

  public addComment(taskId: string, authorId: string, text: string): Comment {
    const newComment: Comment = {
      id: randomUUID(),
      taskId,
      authorId,
      text,
      createdAt: Date.now(),
    };
    this.comments.set(newComment.id, newComment);

    // Publish event
    this.eventBus.publish<CommentAddedEvent>('comment.added', {
      commentId: newComment.id,
      taskId: newComment.taskId,
      authorId: newComment.authorId,
      text: newComment.text,
    });

    return newComment;
  }

  public getCommentById(id: string): Comment | undefined {
    return this.comments.get(id);
  }

  public getCommentsByTaskId(taskId: string): Comment[] {
    return Array.from(this.comments.values()).filter(comment => comment.taskId === taskId);
  }

  public deleteComment(id: string): boolean {
    return this.comments.delete(id);
  }
}
